changeSet.sql:
ALTER TABLE roles ADD COLUMN scope varchar(16);
ALTER TABLE roles ADD CONSTRAINT chk_roles_scope CHECK (scope IS NULL OR scope IN ('COMPANY', 'BRANCH', 'EITHER'));
UPDATE roles SET scope = 'COMPANY' WHERE code = 'executive_director';
UPDATE roles SET scope = 'BRANCH'  WHERE code = 'branch_manager';
UPDATE roles SET scope = 'EITHER'
 WHERE code IN ('sales_manager', 'surveyor_project_manager', 'finance_officer', 'legal_officer');
COMMENT ON COLUMN roles.scope IS
    'How a tenant may assign this role: COMPANY (organisation-wide only), BRANCH (must name a branch), EITHER, or NULL (not assignable by a tenant).';

CREATE TABLE staff_invitations ( id uuid NOT NULL PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES organizations (id), branch_id uuid, created_at timestamp(6) with time zone NOT NULL, updated_at timestamp(6) with time zone, created_by varchar(255), updated_by varchar(255), deleted boolean NOT NULL,
email varchar(255) NOT NULL, first_name varchar(255) NOT NULL, last_name varchar(255) NOT NULL, phone varchar(32), role_id uuid NOT NULL REFERENCES roles (id), scoped_branch_id uuid REFERENCES branches (id), company_name varchar(255) NOT NULL, branch_name varchar(255), role_name varchar(255) NOT NULL, invited_by uuid NOT NULL REFERENCES users (id), token_hash varchar(64) NOT NULL UNIQUE, expires_at timestamp(6) with time zone NOT NULL, send_count integer NOT NULL DEFAULT 1, last_sent_at timestamp(6) with time zone NOT NULL, accepted_at timestamp(6) with time zone, accepted_user_id uuid REFERENCES users (id), revoked_at timestamp(6) with time zone, revoked_by uuid REFERENCES users (id),
CONSTRAINT chk_staff_invitations_one_outcome CHECK (accepted_at IS NULL OR revoked_at IS NULL), CONSTRAINT chk_staff_invitations_accepted_user CHECK ((accepted_at IS NULL) = (accepted_user_id IS NULL)) ); CREATE INDEX idx_staff_invitations_tenant ON staff_invitations (tenant_id, created_at DESC); -- At most one open invitation per email per company; a fresh one is -- a resend, not a duplicate. Closed ones are history and don't count. CREATE UNIQUE INDEX uq_staff_invitations_open_email ON staff_invitations (tenant_id, lower(email)) WHERE accepted_at IS NULL AND revoked_at IS NULL AND deleted = false; COMMENT ON TABLE staff_invitations IS 'Tenant staff invitations (SI-1..SI-7). Token stored hashed. Not RLS-policied: reached pre-auth by token hash. See AGENTS.md.';
